-- Tutorial is folded into Recall: an article's Tutorial conversation joins its
-- Recall one, every other Tutorial thread becomes a Recall thread, and the
-- kind `tutorial` leaves the constraint and its one-per-article index.
-- docs/plans/261020m-recall-and-tutorial-become-one-recall.md § Stored data,
-- and § Changed by GPT Sol's plan review (F1, F8).
--
-- Generated by drizzle-kit (the three DDL statements: drop the CHECK, drop the
-- index, re-add the CHECK), then the data movement was inserted by hand
-- between the DROP INDEX and the ADD. That order is the whole point, the trap
-- 0048_rename_review_thread_kind.sql wrote down: Postgres validates a re-added
-- CHECK against the rows already in the table, so narrowing it before the
-- rows move fails with a 23514 — and only where there is history, passing
-- cleanly on an empty container. `drizzle-kit generate` diffs
-- src/db/schema.ts and cannot see a data movement, so a reader regenerating
-- this file gets the three statements without it, and that file would be
-- wrong.
--
-- Production, read-only on 2026-10-20: 9 `learn` threads, 2 `tutorial`
-- threads (6 messages), and one article that has both.
--
-- **Keeper is the Recall thread**, not the earlier one (20261001143901 kept
-- the earliest): its id is the one the Recall screen, Live sessions and
-- `?thread=` links already name.
--
-- **Fails loudly rather than losing anything.** The migrator runs every
-- pending file in one transaction, so any RAISE or constraint violation below
-- leaves the database exactly as it was:
--   - a pending answer with a live attempt in a thread being folded RAISEs
--     (its writer matches on the old thread id and would be orphaned);
--   - a moved message with an @-mention RAISEs (F1): `chat_mentions_message_fk`
--     is ON UPDATE NO ACTION, so moving it would fail anyway, less legibly.
--     The route allows mentions only in Chat, and production had none;
--   - a moved message whose id is already in the kept thread violates
--     `chat_messages`' primary key — deliberately no `on conflict do nothing`,
--     which would drop a turn in silence;
--   - a `tutorial` row that survives the UPDATE fails the re-added CHECK.
--
-- **Code that does not know about this yet** (the deploy before this one, or
-- another worktree on the shared local database) reads a folded or renamed
-- row as `learn`, which it knows. Old code *inserting* a `tutorial` thread
-- fails the CHECK: one failed turn, which a reload fixes once the new code is
-- serving. The new code reads a request's `kind: "tutorial"` as `learn` (F9).

-- No instance still running the old code may insert a Tutorial thread, or a
-- message into one, between the fold and the CHECK. SHARE ROW EXCLUSIVE blocks
-- every writer of chat_threads and is held to the end of the transaction;
-- readers carry on.
LOCK TABLE "spideryarn"."chat_threads" IN SHARE ROW EXCLUSIVE MODE;--> statement-breakpoint

-- The mapping every later statement is driven by: one row per article that has
-- both, naming the Tutorial thread folded away and the Recall thread kept.
-- Each kind is at most one per article (the two partial unique indexes), so
-- the join is one-to-one.
CREATE TEMP TABLE "tutorial_fold" ON COMMIT DROP AS
SELECT "t"."article_id", "t"."id" AS "folded_id", "l"."id" AS "kept_id"
FROM "spideryarn"."chat_threads" "t"
JOIN "spideryarn"."chat_threads" "l"
  ON "l"."article_id" = "t"."article_id" AND "l"."kind" = 'learn'
WHERE "t"."kind" = 'tutorial';--> statement-breakpoint

-- Refuse to fold a thread with an answer still being written, or a message
-- carrying an @-mention (F1). If either fires, wait for the answer (or the
-- sweep) or look at the mention, and migrate again.
DO $$
DECLARE
  "mention" record;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM "spideryarn"."chat_messages" "m"
    JOIN "tutorial_fold" "f"
      ON "m"."article_id" = "f"."article_id" AND "m"."thread_id" = "f"."folded_id"
    WHERE "m"."status" = 'pending' AND "m"."attempt_id" IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'fold_tutorial_into_recall: a Tutorial thread to be folded has an answer still in flight; nothing was changed';
  END IF;

  -- Code review F1: the folded row is deleted, and with it a title the
  -- reader typed. Production had none renamed (2026-10-20); one that appears
  -- is for a person to settle, not this file.
  IF EXISTS (
    SELECT 1
    FROM "spideryarn"."chat_threads" "t"
    JOIN "tutorial_fold" "f"
      ON "t"."article_id" = "f"."article_id" AND "t"."id" = "f"."folded_id"
    WHERE "t"."renamed_at" IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'fold_tutorial_into_recall: a Tutorial thread to be folded was renamed by its reader, and its title would be lost; nothing was changed';
  END IF;

  SELECT "cm"."article_id", "cm"."thread_id", "cm"."message_id" INTO "mention"
  FROM "spideryarn"."chat_mentions" "cm"
  JOIN "tutorial_fold" "f"
    ON "cm"."article_id" = "f"."article_id" AND "cm"."thread_id" = "f"."folded_id"
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'fold_tutorial_into_recall: message % in Tutorial thread % (article %) has an @-mention, which cannot move; nothing was changed',
      "mention"."message_id", "mention"."thread_id", "mention"."article_id";
  END IF;
END
$$;--> statement-breakpoint

-- Move the Tutorial thread's messages into the Recall thread, after the Recall
-- thread's last turn and in their own order — never interleaved by timestamp,
-- which could separate a question from its answer. Numbering starts at the
-- keeper's max(ordinal) + 1, not its count, so a keeper with a gap cannot
-- collide. Only thread_id and ordinal change; every other column stays.
UPDATE "spideryarn"."chat_messages" "m"
SET "thread_id" = "mv"."kept_id", "ordinal" = "mv"."new_ordinal"
FROM (
  SELECT
    "msg"."article_id",
    "msg"."thread_id",
    "msg"."id",
    "f"."kept_id",
    coalesce((
      SELECT max("k"."ordinal")
      FROM "spideryarn"."chat_messages" "k"
      WHERE "k"."article_id" = "f"."article_id" AND "k"."thread_id" = "f"."kept_id"
    ), -1)
    + row_number() OVER (
      PARTITION BY "f"."article_id"
      ORDER BY "msg"."ordinal"
    ) AS "new_ordinal"
  FROM "spideryarn"."chat_messages" "msg"
  JOIN "tutorial_fold" "f"
    ON "msg"."article_id" = "f"."article_id" AND "msg"."thread_id" = "f"."folded_id"
) "mv"
WHERE "m"."article_id" = "mv"."article_id"
  AND "m"."thread_id" = "mv"."thread_id"
  AND "m"."id" = "mv"."id";--> statement-breakpoint

-- F8: the keeper's clock becomes the later of the two, so the conversation
-- sorts by its most recent turn, and its gist is cleared, because the
-- transcript it summarised has grown. Its id, title, kind and created_at are
-- untouched.
UPDATE "spideryarn"."chat_threads" "t"
SET "updated_at" = greatest("t"."updated_at", "ft"."updated_at"),
    "gist" = NULL,
    "gist_at" = NULL
FROM "tutorial_fold" "f"
JOIN "spideryarn"."chat_threads" "ft"
  ON "ft"."article_id" = "f"."article_id" AND "ft"."id" = "f"."folded_id"
WHERE "t"."article_id" = "f"."article_id" AND "t"."id" = "f"."kept_id";--> statement-breakpoint

-- The two advisory pointers at a thread (text, no foreign key), repointed by
-- article AND id: thread ids are only unique within an article.
UPDATE "spideryarn"."realtime_sessions" "r"
SET "thread_id" = "f"."kept_id"
FROM "tutorial_fold" "f"
WHERE "r"."article_id" = "f"."article_id" AND "r"."thread_id" = "f"."folded_id";--> statement-breakpoint

UPDATE "spideryarn"."comments" "c"
SET "thread_id" = "f"."kept_id"
FROM "tutorial_fold" "f"
WHERE "c"."article_id" = "f"."article_id" AND "c"."thread_id" = "f"."folded_id";--> statement-breakpoint

-- The folded threads are empty by now. `chat_messages_thread_fk` cascades, so
-- a message the move missed would go with its thread — the test asserts the
-- count before and after for exactly that reason.
DELETE FROM "spideryarn"."chat_threads" "t"
USING "tutorial_fold" "f"
WHERE "t"."article_id" = "f"."article_id" AND "t"."id" = "f"."folded_id";--> statement-breakpoint

ALTER TABLE "spideryarn"."chat_threads" DROP CONSTRAINT "chat_threads_kind";--> statement-breakpoint
DROP INDEX "spideryarn"."chat_threads_one_tutorial";--> statement-breakpoint

-- Every Tutorial thread left (an article with no Recall thread) becomes the
-- article's Recall thread, keeping its id, title, timestamps, gist and
-- messages. `chat_threads_one_learn` cannot meet a duplicate: these articles
-- had no `learn` row, and the old index held at most one `tutorial` row each.
UPDATE "spideryarn"."chat_threads" SET "kind" = 'learn' WHERE "kind" = 'tutorial';--> statement-breakpoint

-- The postcondition: a single surviving `tutorial` row fails this with 23514,
-- and the whole migration with it.
ALTER TABLE "spideryarn"."chat_threads" ADD CONSTRAINT "chat_threads_kind" CHECK ("spideryarn"."chat_threads"."kind" in ('chat','learn','candidates','explore','guide'));
